// Versioned, one-to-one mapping of the source-checked catalogue to stable course IDs.
const PAGE_QUOTES={"610d153a1860d80871e90b1e":{"id":"q001","text":"Chess problems are the hymn-tunes of mathematics.","attribution":"G. H. Hardy","source_url":"https://en.wikiquote.org/wiki/Chess","verification_note":"Wikiquote cites A Mathematician’s Apology (1941), section 10; book not independently consulted."},"610bd634a68d2d0c3e06e5ca":{"id":"q002","text":"It is eminently and emphatically the philosopher's game.","attribution":"Paul Morphy","source_url":"https://en.wikiquote.org/wiki/Chess","verification_note":"Wikiquote cites Testimonials to Paul Morphy (1859), page 13; original not independently consulted."},"610c00e7735b8353ba06fdab":{"id":"q003","text":"It is not only the most delightful and scientific, but the most moral of amusements.","attribution":"Paul Morphy","source_url":"https://en.wikiquote.org/wiki/Chess","verification_note":"Wikiquote cites Testimonials to Paul Morphy (1859), page 13; original not independently consulted."},"610ceee11860d80871e8d694":{"id":"q004","text":"Chess can convey as much happiness as a good book or work of music can.","attribution":"Tigran Petrosian","source_url":"https://en.wikiquote.org/wiki/Chess","verification_note":"Sentence excerpt; Wikiquote cites Achilleas Zographos, Music and Chess (2017), p. 114; original not independently consulted."},"610c106f735b8353ba07294e":{"id":"q005","text":"I have played over several hundred of Morphy's games, and am continually surprised and entertained by his ingenuity.","attribution":"Bobby Fischer","source_url":"https://en.wikiquote.org/wiki/Chess","verification_note":"Wikiquote cites Chessworld (January–February 1964), pp. 56–61; original not independently consulted."},"610c00e7735b8353ba06fd81":{"id":"q006","text":"You should keep in mind no names, nor numbers, nor isolated incidents, not even results, but only methods.","attribution":"Emanuel Lasker","source_url":"https://en.wikiquote.org/wiki/Emanuel_Lasker","verification_note":"Sentence excerpt; Wikiquote cites Lasker’s Manual of Chess, p. 338; original not independently consulted."},"610d1e581860d80871e91fa1":{"id":"q007","text":"Without error there can be no brilliancy.","attribution":"Commonly attributed to Emanuel Lasker","source_url":"https://en.wikiquote.org/wiki/Emanuel_Lasker","verification_note":"Disputed: Wikiquote says no original source is known, and cites its appearance in Larry Evans’s Chess Catechism (1970)."},"610bdfa0cb7c350b0ba44a08":{"id":"q008","text":"In conclusion, if you want to unravel the multitude of secrets of chess then don't begrudge the time.","attribution":"Garry Kasparov","source_url":"https://en.wikiquote.org/wiki/Garry_Kasparov","verification_note":"Wikiquote cites Learn Chess with Garry Kasparov (2003); original not independently consulted."},"610bd92ca68d2d0c3e06f04a":{"id":"q009","text":"I love the game, and I love to compete, but I am not obsessed with the struggle.","attribution":"Magnus Carlsen","source_url":"https://en.wikiquote.org/wiki/Magnus_Carlsen","verification_note":"Wikiquote cites Eben Harrell’s TIME interview, 25 December 2009; original interview not independently consulted."},"610bd92ba68d2d0c3e06eff8":{"id":"q010","text":"I get more upset at losing at other things than chess. I always get upset when I lose at Monopoly.","attribution":"Magnus Carlsen","source_url":"https://en.wikiquote.org/wiki/Magnus_Carlsen","verification_note":"Wikiquote cites a New York Times interview; original interview not independently consulted."},"610ceee11860d80871e8d676":{"id":"q011","text":"In order to improve your game you must study the endgame before anything else; for, whereas the endings can be studied and mastered by themselves, the middlegame and the opening must be studied in relation to the endgame.","attribution":"José Raúl Capablanca","source_url":"https://en.wikiquote.org/wiki/Jos%C3%A9_Ra%C3%BAl_Capablanca","verification_note":"Wikiquote cites Capablanca’s Last Chess Lectures (1966), p. 23; original not independently consulted."},"610d030b1860d80871e8e1c1":{"id":"q012","text":"Play the opening like a book, the middle game like a magician, and the endgame like a machine.","attribution":"Rudolf Spielmann","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c037a735b8353ba0709d0":{"id":"q013","text":"Sometimes a Pawn is enough to change the whole game and those who ignore the importance of it, are liable to lose their Queen.","attribution":"Sandeep Sharma","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bfd38735b8353ba06f32c":{"id":"q014","text":"Half the variations which are calculated in a tournament game turn out to be completely superfluous. Unfortunately, no one knows in advance which half.","attribution":"Jan Timman","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e8735b8353ba06fe61":{"id":"q015","text":"The winner is the one who makes the next-to-last mistake.","attribution":"Savielly Tartakower","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e9735b8353ba06ff1b":{"id":"q016","text":"The only thing chess players have in common is chess.","attribution":"Lodewijk Prins","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdc68cb7c350b0ba43fd1":{"id":"q017","text":"The Pin is mightier than the sword","attribution":"Fred Reinfeld","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072912":{"id":"q018","text":"Strategy requires thought, tactics require observation","attribution":"Max Euwe","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca28":{"id":"q019","text":"All that matters on the chessboard is good moves.","attribution":"Bobby Fischer","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdc68cb7c350b0ba43fd7":{"id":"q020","text":"I go over many games collections and pick up something from the style of each player.","attribution":"Mikhail Tal","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d030a1860d80871e8e129":{"id":"q021","text":"Every chess master was once a beginner.","attribution":"Irving Chernev","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba07297e":{"id":"q022","text":"Chess does not drive people mad, it keeps mad people sane.","attribution":"Bill Hartston","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072954":{"id":"q023","text":"In chess, as it is played by the masters, chance is practically eliminated.","attribution":"Emanuel Lasker","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca2e":{"id":"q024","text":"I started by just sitting by the chessboard exploring things. I didn’t even have books at first, and I just played by myself. I learnt a lot from that, and I feel that it is a big reason why I now have a good intuitive understanding of chess.","attribution":"Magnus Carlsen","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c060c735b8353ba071438":{"id":"q025","text":"It’s always better to sacrifice your opponent’s men.","attribution":"Savielly Tartakower","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e8735b8353ba06fe85":{"id":"q026","text":"When the chess game is over, the pawn and the king go back to the same box.","attribution":"Traditional proverb","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Chess Journal calls this an Irish saying, but its geographic origin is unverified."},"610ceee11860d80871e8d66a":{"id":"q027","text":"Chess is a sea in which a gnat may drink and an elephant may bathe.","attribution":"Hindu proverb","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf57a735b8353ba06d45b":{"id":"q028","text":"If you don’t know what to do, find your worst piece and look for a better square.","attribution":"Gerald Schwarz","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca08":{"id":"q029","text":"Pawns are born free, yet they are everywhere in chains.","attribution":"Rick Kennedy","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c0936735b8353ba071e8c":{"id":"q030","text":"Chess is the art of analysis.","attribution":"Mikhail Botvinnik","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca1a":{"id":"q031","text":"The blunders are all there on the board, waiting to be made.","attribution":"Savielly Tartakower","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e8735b8353ba06fee5":{"id":"q032","text":"The essence of Chess is thinking about what Chess is.","attribution":"David Bronstein","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610ceee11860d80871e8d688":{"id":"q033","text":"After a bad opening, there is hope for the middle game. After a bad middle game, there is hope for the endgame. But once you are in the endgame, the moment of truth has arrived.","attribution":"Edmar Mednis","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d153a1860d80871e90b4a":{"id":"q034","text":"Nothing excites jaded Grandmasters more than a theoretical novelty","attribution":"Dominic Lawson","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf57a735b8353ba06d457":{"id":"q035","text":"Of chess, it has been said that life is not long enough for it, but that is the fault of life, not chess.","attribution":"William Napier","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd92ca68d2d0c3e06f03a":{"id":"q036","text":"You may learn much more from a game you lose than from a game you win. You will have to lose hundreds of games before becoming a good player.","attribution":"José Raúl Capablanca","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d153a1860d80871e90b50":{"id":"q037","text":"If you have made a mistake or committed an inaccuracy there is no need to become annoyed and to think that everything is lost. You have to reorientate yourself quickly and find a new plan in the new situation.","attribution":"David Bronstein","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf7d5735b8353ba06dec6":{"id":"q038","text":"No one ever won a game by resigning.","attribution":"Savielly Tartakower","source_url":"https://www.chessjournal.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d054a1860d80871e8ebee":{"id":"q039","text":"Even the laziest King flees wildly in the face of a double check!","attribution":"Aron Nimzowitsch","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified. Author spelling normalized from Aaron."},"610bd634a68d2d0c3e06e5fa":{"id":"q040","text":"Chess is rarely a game of ideal moves. Almost always, a player faces a series of difficult consequences whichever move he makes.","attribution":"David Shenk","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d0a871860d80871e8f649":{"id":"q041","text":"Even a poor plan is better than no plan at all.","attribution":"Mikhail Chigorin","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c060c735b8353ba071460":{"id":"q042","text":"Tactics is knowing what to do when there is something to do; strategy is knowing what to do when there is nothing to do.","attribution":"Savielly Tartakower","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d054a1860d80871e8ebba":{"id":"q043","text":"In life, as in chess, forethought wins.","attribution":"Charles Buxton","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d054a1860d80871e8ec12":{"id":"q044","text":"A good player is always lucky.","attribution":"Jose Raul Capablanca","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bfd39735b8353ba06f332":{"id":"q045","text":"Help your pieces so they can help you.","attribution":"Paul Morphy","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072908":{"id":"q046","text":"Chess is a fairy tale of 1001 blunders","attribution":"Savielly Tartakower","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf57a735b8353ba06d467":{"id":"q047","text":"It doesn’t matter how strong a player you are, if you fail to register some development in the opening, then you are asking for trouble.","attribution":"John Emms","source_url":"https://www.chess-universe.shop/en-us/blogs/news/64-quotes-about-chess","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d153a1860d80871e90b5a":{"id":"q048","text":"Critical thinking is the most important factor with chess. As it is in life, you need to think before you make decisions.","attribution":"Hikaru Nakamura","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072946":{"id":"q049","text":"In chess, knowledge is a very transient thing. It changes so fast that even a single mouse slip sometimes changes the evaluation.","attribution":"Viswanathan Anand","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd634a68d2d0c3e06e5f0":{"id":"q050","text":"That’s what Chess is all about. One day you give your opponent a lesson, the next day he gives you one.","attribution":"Bobby Fischer","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdfa1cb7c350b0ba44a44":{"id":"q051","text":"In life, unlike chess, the game continues after checkmate.","attribution":"Isaac Asimov","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdfa0cb7c350b0ba44a20":{"id":"q052","text":"The most interesting thing to me in chess is not the gambits. Or the moves. It’s the mental toughness.","attribution":"Edward Zwick","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bfd38735b8353ba06f316":{"id":"q053","text":"I spend hours playing chess because I find it so much fun. The day it stops being fun is the day I give up.","attribution":"Magnus Carlsen","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d030b1860d80871e8e189":{"id":"q054","text":"There are more adventures on a chessboard than on all the seas of the world.","attribution":"Pierre Mac Orlan","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1ad61860d80871e9157f":{"id":"q055","text":"You can only get good at chess if you love the game.","attribution":"Bobby Fischer","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1ad61860d80871e91579":{"id":"q056","text":"I prefer to lose a really good game than to win a bad one.","attribution":"David Levy","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c060c735b8353ba07140e":{"id":"q057","text":"Chess is life and every game is like a new life.","attribution":"Eduard Gufeld","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d153a1860d80871e90b54":{"id":"q058","text":"Chess is played with the mind and not with the hands.","attribution":"Renaud and Kahn","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdfa1cb7c350b0ba44a60":{"id":"q059","text":"In chess, one cannot control everything. Sometimes a game takes an unexpected turn, in which beauty begins to emerge. Both players are always instrumental in this.","attribution":"Vladimir Kramnik","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca42":{"id":"q060","text":"The move is there, but you must see it.","attribution":"Savielly Tartakower","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d0a871860d80871e8f633":{"id":"q061","text":"Zugzwang. It’s when you have no good moves. But you still have to move.","attribution":"Michael Chabon","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072932":{"id":"q062","text":"Chess is everything: art, science, and sport.","attribution":"Anatoly Karpov","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d0f2a1860d80871e900b5":{"id":"q063","text":"Of course, errors are not good for a chess game, but errors are unavoidable and in any case, a game without errors, or as they say ‘flawless game’ is colorless.","attribution":"Mikhail Tal","source_url":"https://chessdelta.com/greatest-chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c037a735b8353ba0709d4":{"id":"q064","text":"When in doubt -- play chess.","attribution":"Walter Tevis","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e9735b8353ba06ffc7":{"id":"q065","text":"The older I grow, the more I value Pawns.","attribution":"Paul Keres","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e7735b8353ba06fd5d":{"id":"q066","text":"Some part of a mistake is always correct.","attribution":"Savielly Tartakower","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified. Author spelling normalized from Tartakover."},"610bd634a68d2d0c3e06e5ce":{"id":"q067","text":"Pawn endings are to chess what putting is to golf.","attribution":"C. J. S. Purdy","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1ad61860d80871e91585":{"id":"q068","text":"To avoid losing a piece, many a person has lost the game.","attribution":"Savielly Tartakower","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified. Author spelling normalized from Tartakover."},"610bfd38735b8353ba06f310":{"id":"q069","text":"Openings teach you openings. Endgames teach you chess!","attribution":"Stephan Gerzadowicz","source_url":"https://exeterchessclub.org.uk/content/chess-quotes","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf2fd735b8353ba06ca20":{"id":"q070","text":"The willingness to take risks is essential for a player to improve.","attribution":"Viktor Korchnoi","source_url":"https://chess-teacher.com/chess-quotes-motivational-and-instructional/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1ad61860d80871e91575":{"id":"q071","text":"The king is a strong piece—use it!","attribution":"Wilhelm Steinitz","source_url":"https://chess-teacher.com/chess-quotes-motivational-and-instructional/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c106f735b8353ba072904":{"id":"q072","text":"No one will regret the time dedicated to chess, as it will help in any profession","attribution":"Tigran Petrosian","source_url":"https://woochess.com/en/blog/20-chess-quotes-from-professionals-to-increase-motivation","verification_note":"Wording and attribution checked against WooChess, which spells the surname Petrosyan; original source and translation not independently verified."},"610bf57a735b8353ba06d479":{"id":"q073","text":"Chess first of all teaches you to be objective.","attribution":"Alexander Alekhine","source_url":"https://en.wikiquote.org/wiki/Alexander_Alekhine","verification_note":"Wikiquote cites The Soviet School of Chess (2001), p. 42; that source was not independently inspected."},"610d1e581860d80871e91f95":{"id":"q074","text":"An invitation is not an obligation.","attribution":"Igor Smirnov","source_url":"https://chess-teacher.com/chess-quotes-motivational-and-instructional/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd92ca68d2d0c3e06f018":{"id":"q075","text":"I have come to the personal conclusion that while all artists are not chess players, all chess players are artists.","attribution":"Marcel Duchamp","source_url":"https://chess-teacher.com/chess-quotes-motivational-and-instructional/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bfd39735b8353ba06f33c":{"id":"q076","text":"Chess has this in common with making poetry; that the desire for it comes upon the amateur in gusts.","attribution":"A. A. Milne","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf57a735b8353ba06d461":{"id":"q077","text":"The beauty and creativity of chess masterpieces as an art form gives me a sense of musical inspiration and wonder about what the human mind is capable of.","attribution":"Keith Oxman","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e9735b8353ba06ff97":{"id":"q078","text":"Chess study is a great foundation for anyone who works with data processing because it teaches you how to analyze, classify data, and recognize patterns.","attribution":"Michael Ginat","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bdfa1cb7c350b0ba44a5a":{"id":"q079","text":"Chess is a very positive way to exercise your mind.","attribution":"Barney Chavous","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified. Sentence excerpt from a longer quotation."},"610d030b1860d80871e8e1b5":{"id":"q080","text":"The chess pieces are the block alphabet, which shapes thoughts; and these thoughts, although making a visual design on the chessboard, express their beauty abstractly, like a poem.","attribution":"Marcel Duchamp","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1e581860d80871e91f8d":{"id":"q081","text":"The game of chess is a highly rigorous process which nevertheless allows for a considerable degree of imagination and intuition.","attribution":"Rodney Cottrell","source_url":"https://coloradomasterchess.com/chess-quotes/","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified. Sentence excerpt from a longer quotation."},"610d0a871860d80871e8f651":{"id":"q082","text":"Chess, like love, like music, has the power to make men happy.","attribution":"Siegbert Tarrasch","source_url":"https://en.wikiquote.org/wiki/Siegbert_Tarrasch","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610c00e7735b8353ba06fd59":{"id":"q083","text":"Many have become Chess Masters, no one has become the Master of Chess.","attribution":"Siegbert Tarrasch","source_url":"https://en.wikiquote.org/wiki/Siegbert_Tarrasch","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610d0a871860d80871e8f62b":{"id":"q084","text":"In tournaments it is not enough to be a connoisseur of chess; one must also play well.","attribution":"Siegbert Tarrasch","source_url":"https://en.wikiquote.org/wiki/Siegbert_Tarrasch","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610c0936735b8353ba071ea4":{"id":"q085","text":"Before the endgame, the Gods have placed the middle game.","attribution":"Siegbert Tarrasch","source_url":"https://en.wikiquote.org/wiki/Siegbert_Tarrasch","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610bd634a68d2d0c3e06e5e4":{"id":"q086","text":"The beauty of a move lies not in its appearance but in the thought behind it.","attribution":"Aron Nimzowitsch","source_url":"https://en.wikiquote.org/wiki/Aron_Nimzowitsch","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610d030a1860d80871e8e12d":{"id":"q087","text":"Later, I began to succeed in decisive games, perhaps because I realised a very simple truth: not only was I worried, but so was my opponent.","attribution":"Mikhail Tal","source_url":"https://en.wikiquote.org/wiki/Mikhail_Tal","verification_note":"Wording and attribution checked against Wikiquote; the original source cited there was not independently inspected."},"610bf2fd735b8353ba06ca0e":{"id":"q088","text":"There are two kinds of sacrifices: correct ones, and mine.","attribution":"Commonly attributed to Mikhail Tal","source_url":"https://en.wikiquote.org/wiki/Mikhail_Tal","verification_note":"Wikiquote calls this widely attributed to Tal, but says no original source is known."},"610d0a871860d80871e8f659":{"id":"q089","text":"Pawns are the soul of the game.","attribution":"François-André Danican Philidor","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Modern English translation quoted by this collection; the original French wording and translation provenance were not independently inspected."},"610d030b1860d80871e8e1a1":{"id":"q090","text":"Chess, it’s the struggle against the error.","attribution":"Johannes Zukertort","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bf7d5735b8353ba06debc":{"id":"q091","text":"The hardest game to win is a won game.","attribution":"Emanuel Lasker","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610d1e581860d80871e91f99":{"id":"q092","text":"There is no remorse like the remorse of chess.","attribution":"H. G. Wells","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bfd38735b8353ba06f2c8":{"id":"q093","text":"I always loved complexity. With chess, one creates beautiful problems.","attribution":"Marcel Duchamp","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610ceee11860d80871e8d670":{"id":"q094","text":"Chess is a game by its form, an art by its content and a science by the difficulty of gaining mastery in it.","attribution":"Tigran Petrosian","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd633a68d2d0c3e06e5bc":{"id":"q095","text":"I don’t believe in psychology. I believe in good moves.","attribution":"Bobby Fischer","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c037a735b8353ba0709ea":{"id":"q096","text":"If your opponent offers you a draw, try to work out why he thinks he's worse off.","attribution":"Nigel Short","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd92ca68d2d0c3e06f012":{"id":"q097","text":"Modern chess is too much concerned with things like pawn structure. Forget it, checkmate ends the game.","attribution":"Nigel Short","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c00e8735b8353ba06fe05":{"id":"q098","text":"Age brings wisdom to some men, and to others chess.","attribution":"Evan Esar","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610bd92ca68d2d0c3e06f062":{"id":"q099","text":"Avoid the crowd. Do your own thinking independently. Be the chess player, not the chess piece.","attribution":"Ralph Charell","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Wording and attribution checked against this accessible quote collection; original source and attribution not independently verified."},"610c060c735b8353ba071404":{"id":"q100","text":"Chess is the gymnasium of the mind.","attribution":"Commonly attributed to Blaise Pascal","source_url":"https://enthu.com/blog/chess/39-inspiring-chess-quotes-for-you","verification_note":"Collection attributes this to Pascal; Exeter Chess Club notes the attribution is uncertain. Original source not established."}};
function quoteBubble(id,pose){const q=PAGE_QUOTES[id];if(!q)return null;const box=text('blockquote','','quote-bubble');box.append(text('p','“'+q.text+'”'),text('cite',q.attribution));const detail=text('details');detail.append(text('summary','Source and attribution'));const a=text('a','Source');a.href=q.source_url;a.target='_blank';a.rel='noopener noreferrer';detail.append(a,text('p',q.verification_note));box.append(detail);return box}
function characterCards(){const names=[['Steve','The Beginner'],['Mark','The Club Player'],['Max','The Caveman'],['Beth','The Grinder'],['Hal','The Silicon Beast'],['Magnus','The Champ']];const cards=text('div','','cast-grid');names.forEach(([name,role],i)=>{const card=text('div','','cast-card cast-'+i),im=document.createElement('img');im.src=`c0${i+1}-happy.png`;im.alt='';im.loading='lazy';card.append(im,text('strong',name),text('span',role));cards.append(card)});return cards}

