function clean(html){const source=new DOMParser().parseFromString(html||'','text/html');const target=document.createDocumentFragment();const allowed=new Set(['P','BR','STRONG','EM','UL','OL','LI','H4','DIV','SPAN','A']);function copy(node,parent){if(node.nodeType===Node.TEXT_NODE){parent.append(document.createTextNode(node.textContent));return}if(node.nodeType!==Node.ELEMENT_NODE)return;if(!allowed.has(node.tagName)){for(const c of node.childNodes)copy(c,parent);return}const e=document.createElement(node.tagName.toLowerCase());if(node.tagName==='A'){try{const url=new URL(node.getAttribute('href'));if(['https:','http:'].includes(url.protocol)){e.href=url.href;e.target='_blank';e.rel='noopener noreferrer'}}catch(_){}}for(const c of node.childNodes)copy(c,e);parent.append(e)}for(const c of source.body.childNodes)copy(c,target);return target}
